mapper.select:
SELECT COUNT(1)
FROM diag_precompute_job j
LEFT JOIN diag_precompute_window w
       ON w.tenant_id = j.tenant_id
      AND w.job_id = j.job_id
WHERE j.tenant_id = #{tenantId}
  AND j.module_code = 'DIAGNOSIS'

      AND TRY_CAST(JSON_VALUE(j.request_json, '$.classLevel') AS INT) = #{req.classLevel}


      AND JSON_VALUE(j.request_json, '$.classNo') IN

          #{classNo}



      AND ISNULL(JSON_VALUE(j.request_json, '$.deptId'), '') = #{req.deptId}


      AND ISNULL(JSON_VALUE(j.request_json, '$.retailTypeId'), '') = #{req.retailTypeId}


      AND ISNULL(JSON_VALUE(j.request_json, '$.businessCircleId'), '') = #{req.businessCircleId}


      AND ISNULL(JSON_VALUE(j.request_json, '$.deptGroupId'), '') = #{req.deptGroupId}


      AND ISNULL(JSON_VALUE(j.request_json, '$.storeNo'), '') = #{req.storeScope}


      AND CONVERT(date, j.read_start) = #{req.periodStart}


      AND CONVERT(date, j.read_end) = #{req.periodEnd}


      AND CONVERT(date, w.compare_start) = #{req.compareStart}


      AND CONVERT(date, w.compare_end) = #{req.compareEnd}


      AND COALESCE(j.submitted_time, j.create_time) >= #{req.createStart}


      AND COALESCE(j.submitted_time, j.create_time) < DATEADD(day, 1, #{req.createEnd})

SELECT j.job_id AS jobId, j.request_hash AS requestHash, j.status_code AS statusCode, j.progress_percent AS progressPercent, j.current_stage AS currentStage, j.submitted_by AS submittedBy, COALESCE(j.submitted_time, j.create_time) AS submittedTime, TRY_CAST(JSON_VALUE(j.request_json, '$.classLevel') AS INT) AS classLevel, JSON_VALUE(j.request_json, '$.classNo') AS classNo, JSON_VALUE(j.request_json, '$.className') AS className, JSON_VALUE(j.request_json, '$.deptId') AS deptId, JSON_VALUE(j.request_json, '$.deptId') AS deptName, JSON_VALUE(j.request_json, '$.retailTypeId') AS retailTypeId, JSON_VALUE(j.request_json, '$.retailTypeId') AS retailTypeName, JSON_VALUE(j.request_json, '$.businessCircleId') AS businessCircleId, JSON_VALUE(j.request_json, '$.businessCircleId') AS businessCircleName, JSON_VALUE(j.request_json, '$.deptGroupId') AS deptGroupId, JSON_VALUE(j.request_json, '$.deptGroupId') AS deptGroupName, JSON_VALUE(j.request_json, '$.storeNo') AS storeNo, JSON_VALUE(j.request_json, '$.storeNo') AS storeName, j.read_start AS periodStart, j.read_end AS periodEnd, w.compare_start AS compareStart, w.compare_end AS compareEnd, w.data_version AS dataVersion, snapshotInfo.snapshotId AS snapshotId, CAST(NULL AS NVARCHAR(128)) AS createByName FROM diag_precompute_job j OUTER APPLY ( SELECT TOP 1 * FROM diag_precompute_window w1 WHERE w1.tenant_id = j.tenant_id AND w1.job_id = j.job_id ORDER BY w1.window_id DESC ) w OUTER APPLY ( SELECT TOP 1 o.id AS snapshotId FROM diag_result_overview o WHERE o.tenant_id = j.tenant_id AND o.query_hash = j.request_hash AND o.data_version = w.data_version ORDER BY o.snapshot_time DESC, o.id DESC ) snapshotInfo WHERE j.tenant_id = #{tenantId} AND j.module_code = 'DIAGNOSIS'
AND TRY_CAST(JSON_VALUE(j.request_json, '$.classLevel') AS INT) = #{req.classLevel}
AND JSON_VALUE(j.request_json, '$.classNo') IN
#{classNo}
AND ISNULL(JSON_VALUE(j.request_json, '$.deptId'), '') = #{req.deptId}
AND ISNULL(JSON_VALUE(j.request_json, '$.retailTypeId'), '') = #{req.retailTypeId}
AND ISNULL(JSON_VALUE(j.request_json, '$.businessCircleId'), '') = #{req.businessCircleId}
AND ISNULL(JSON_VALUE(j.request_json, '$.deptGroupId'), '') = #{req.deptGroupId}
AND ISNULL(JSON_VALUE(j.request_json, '$.storeNo'), '') = #{req.storeScope}
AND j.read_start = #{req.periodStart}
AND j.read_end = #{req.periodEnd}
AND w.compare_start = #{req.compareStart}
AND w.compare_end = #{req.compareEnd}
AND COALESCE(j.submitted_time, j.create_time) >= #{req.createStart}
AND COALESCE(j.submitted_time, j.create_time) < DATEADD(day, 1, #{req.createEnd})
ORDER BY COALESCE(j.submitted_time, j.create_time) DESC, j.job_id DESC OFFSET #{offset} ROWS FETCH NEXT #{limit} ROWS ONLY
